 public static void main(String[]args){Register blocks=new Register(net.minecraft.core.registries.Registries.BLOCK),items=new Register(net.minecraft.core.registries.Registries.ITEM);Nexus.register(blocks);Nexus.register(items);Object goal=Nexus.goal(new Object());ok(goal instanceof NexusGoal,"reflective goal class loads with dotted name");ok(((NexusGoal)goal).getFlags().containsAll(java.util.Set.of(net.minecraft.world.entity.ai.goal.Goal.Flag.MOVE,net.minecraft.world.entity.ai.goal.Goal.Flag.LOOK)),"goal movement flags configured");Tooltip tooltip=new Tooltip(Nexus.ITEM);Nexus.tooltip(tooltip);ok(tooltip.lines.size()==8,"nexus explanation tooltip");Tooltip other=new Tooltip(new Object());Nexus.tooltip(other);ok(other.lines.isEmpty(),"unrelated item tooltip unchanged");ok(blocks.values.size()==1&&items.values.size()==1,"block and item registration");ok(((net.minecraft.world.item.BlockItem)Nexus.ITEM).block==Nexus.BLOCK,"placeable item linked to block");ok(((net.minecraft.world.level.block.Block)Nexus.BLOCK).properties.resistance==3600000,"explosion resistance");ok(Limits.maximum(FactionTier.TEAM)==4,"level 1 limit");ok(Limits.maximum(FactionTier.COLONY)==6,"level 2 limit");ok(Limits.maximum(FactionTier.COUNTRY)==8,"level 3 limit");int[] frequencies=new int[5];for(int i=0;i<100;i++)frequencies[PveRules.rarity(i)]++;ok(Arrays.equals(frequencies,new int[]{60,25,10,4,1}),"rarity probabilities");ok(PveRules.level(99)==1&&PveRules.level(100)==2&&PveRules.level(299)==2&&PveRules.level(300)==3,"XP thresholds");ClanState.Profile base=new ClanState.Profile();ok(Nexus.maxHealth(base)==100,"base health");base.nexusUpgrade=10;ok(Nexus.maxHealth(base)==350,"upgrade health");MinecraftServer server=new MinecraftServer();World world=new World(server);Player chief=new Player(server,world);Faction faction=new Faction("Tribe");Faction capped=new Faction("Cap");for(long i=0;i<4;i++)capped.claims.add(i);ok(!Limits.room(capped,1),"no new claim at cap");capped.claims.remove(3L);ok(Limits.room(capped,1)&&!Limits.room(capped,2),"reserved capture capacity");Faction defender=new Faction("Defender");defender.claims.add(0L);defender.claims.add(1L);defender.capital.add(0L);ok(!Limits.attack(new OperationAttack(0,0),capped,defender),"capital annexation cannot exceed cap");faction.members.put(chief.uuid,FactionRank.CREATOR);faction.claims.add(0L);server.manager.factions.put(faction.id,faction);server.manager.owners.put(0L,faction.id);Clans.bind(server.manager,server);ClanState.Profile profile=Clans.state(server.manager).profile(faction.id);Nexus.BLOCK=new Object();BlockEvent place=new BlockEvent(world,chief);Nexus.place(place);ok(!place.canceled&&profile.nexusPlaced,"placement in claimed territory");BlockEvent duplicate=new BlockEvent(world,chief);Nexus.place(duplicate);ok(duplicate.canceled,"single nexus");Pve.Wave wave=new Pve.Wave(faction.id,world,0,0,0);wave.health=100;wave.participants.add(chief.uuid);Pve.waves.put(faction.id,wave);BlockEvent breaking=new BlockEvent(world,chief);Nexus.breakBlock(breaking);ok(breaking.canceled,"no player break during defense");Mob zombie=new Mob(world);Pve.outline(world,zombie);ok(zombie.glowing&&world.board.team.color==net.minecraft.ChatFormatting.RED&&world.board.entries.contains(zombie.id.toString()),"wave enemies have red glowing outline");Pve.clearOutline(world,zombie.id);ok(world.board.entries.isEmpty(),"outline scoreboard entries cleaned");Join natural=new Join(world,zombie);Pve.join(natural);ok(natural.canceled,"natural zombie blocked in claimed chunk");Join loaded=new Join(world,zombie);loaded.loaded=true;Pve.join(loaded);ok(!loaded.canceled,"existing saved entity kept");zombie.tag.putString("FactionPveWave",wave.id.toString());Join permitted=new Join(world,zombie);Pve.join(permitted);ok(!permitted.canceled,"defense zombie permitted");profile.nexusPos=world.nexus.asLong();Nexus.mobTick(zombie);ok(wave.health==95,"zombie hit 5");server.time=1;Nexus.mobTick(zombie);ok(wave.health==95,"individual hit cooldown");server.time=20;zombie.type="mutantszombies:mutant_brute";Nexus.mobTick(zombie);ok(wave.health==85,"mutant hit 10");wave.pending=0;wave.alive=0;server.time=21;Pve.tick(server);ok(wave.stage==2&&wave.pending==12&&wave.health==85,"next phase retains nexus life with offset clock");wave.pending=0;wave.alive=0;Pve.tick(server);ok(wave.stage==3&&wave.health==85,"third phase retains life");wave.pending=0;wave.alive=0;wave.killed=36;Pve.tick(server);ok(!Pve.waves.containsKey(faction.id)&&profile.pveXp==20&&profile.pveWins==1,"completed run rewards once");ok(profile.pveNext==6021&&!profile.rewards.isEmpty(),"five minute cooldown and loot");Pve.tick(server);ok(profile.pveWins==1,"no duplicate reward");Pve.end(server,server.manager,wave,true);ok(profile.pveWins==1&&profile.pveXp==20,"repeated finalization cannot pay twice");Pve.Wave next=new Pve.Wave(faction.id,world,0,1,server.time);next.health=Nexus.maxHealth(profile);next.participants.add(chief.uuid);Pve.waves.put(faction.id,next);ok(next.health==100,"new run resets health");Pve.death(new Death(chief,new Source(zombie)));ok(!Pve.waves.containsKey(faction.id)&&profile.pveWins==1,"all participant deaths fail without rewards");Pve.Wave destroyed=new Pve.Wave(faction.id,world,0,0,0);destroyed.health=5;destroyed.participants.add(chief.uuid);Pve.waves.put(faction.id,destroyed);zombie.tag.putString("FactionPveWave",destroyed.id.toString());server.time=40;Nexus.mobTick(zombie);ok(world.destroyed&&!profile.nexusPlaced&&!Pve.waves.containsKey(faction.id),"nexus destroyed fails");for(int i=0;i<500;i++){int[] candidate=Pve.candidate(-550,-618);int dx=Math.abs(candidate[0]+550),dz=Math.abs(candidate[1]+618);if(dx>32||dz>32||Math.max(dx,dz)<8)throw new AssertionError("candidate ring");}ok(true,"spawn candidates surround nexus, including neighboring negative chunks");Pve.Wave abandoned=new Pve.Wave(faction.id,world,0,0,server.time);abandoned.health=100;abandoned.participants.add(chief.uuid);chief.chunkX=0;ok(Pve.inside(server.manager,abandoned,chief),"claimed territory participant eligible");chief.chunkX=1;ok(!Pve.inside(server.manager,abandoned,chief),"participant outside claims rejected");profile.nexusPlaced=true;profile.nexusPos=world.nexus.asLong();abandoned.pending=0;abandoned.alive=1;abandoned.deadline=0;Pve.waves.put(faction.id,abandoned);Pve.tick(server);ok(Pve.waves.containsKey(faction.id)&&profile.pveWins==1,"leaving territory and old deadline do not end defense");Pve.keepLoaded(abandoned);ok(world.chunks.tickets.size()==25,"nexus surroundings stay ticking when defenders leave");Pve.Wave overlap=new Pve.Wave(UUID.randomUUID(),world,0,0,server.time);Pve.keepLoaded(overlap);ok(world.chunks.tickets.size()==50,"overlapping defenses own independent tickets");Pve.releaseLoaded(overlap);ok(world.chunks.tickets.size()==25,"releasing overlap preserves active defense");List<Mob> ending=new ArrayList<>();for(int i=0;i<13;i++){Mob mob=new Mob(world);ending.add(mob);world.entities.put(mob.id,mob);abandoned.mobs.add(mob.id);Pve.outline(world,mob);}long ended=server.time;Pve.end(server,server.manager,abandoned,false);ok(!Pve.waves.containsKey(faction.id)&&ending.stream().noneMatch(mob->!mob.alive||mob.discarded),"loss schedules cleanup without instantly removing enemies");Pve.cleanupTick(server);ok(ending.stream().allMatch(mob->mob.alive),"cleanup waits before first deaths");server.time=ended+20;Pve.cleanupTick(server);ok(ending.stream().filter(mob->!mob.alive).count()==2&&ending.stream().noneMatch(mob->mob.discarded),"first group dies with time for death animation");ok(world.chunks.tickets.size()==25,"nexus remains loaded during gradual deaths");server.time=ended+40;Pve.cleanupTick(server);ok(ending.stream().filter(mob->mob.discarded).count()==2,"previous group removed after death animation");for(int i=3;i<=9;i++){server.time=ended+20*i;Pve.cleanupTick(server);}ok(ending.stream().allMatch(mob->mob.discarded)&&Pve.cleanups.isEmpty()&&world.chunks.tickets.isEmpty(),"cleanup finishes and releases all tickets");ok(world.board.entries.isEmpty()&&profile.pveWins==1&&profile.pveXp==20,"cleanup leaves no outlines and gives no failure rewards");chief.chunkX=0;CompoundTag saved=new CompoundTag();profile.nexusUpgrade=3;Clans.save(server.manager,saved);me.danialisntcool.factionfriction.data.FactionManager restored=new me.danialisntcool.factionfriction.data.FactionManager();Clans.load(restored,saved);ClanState.Profile restoredProfile=Clans.state(restored).profile(faction.id);ok(restoredProfile.pveXp==20&&restoredProfile.pveWins==1&&restoredProfile.nexusUpgrade==3,"XP ranking and upgrades persist");int[] heights=Siege.heights(-63,318,64);ok(heights.length==381&&heights[0]==64&&heights[1]==65,"first floors preferred over upper floors");Set<Integer> all=new HashSet<>();for(int h:heights)all.add(h);ok(all.size()==381&&all.contains(-63)&&all.contains(317),"all legal heights considered as alternatives");ok(Siege.priority("minecraft:oak_door")<Siege.priority("minecraft:glass")&&Siege.priority("minecraft:glass")<Siege.priority("minecraft:stone"),"doors then windows then solid walls");ok(Siege.protectedBlock("minecraft:barrel",2)&&Siege.protectedBlock(Nexus.ID,2)&&Siege.protectedBlock("minecraft:bedrock",-1)&&!Siege.protectedBlock("minecraft:stone",1.5f),"breaching preserves nexus storage and unbreakable blocks");world.blocks.clear();BlockPos entrance=new BlockPos(1,60,0),destination=new BlockPos(10,60,0);Mob breacher=new Mob(world);breacher.tag.putDouble("SiegeY",60);world.blocks.put(entrance,new State("minecraft:oak_door"));breacher.tag.putInt("SiegeStuck",3);server.time+=20;Siege.tick(breacher,destination);ok(world.blocks.get(entrance).open(),"stalled zombie opens nearby door before breaking wall");world.blocks.put(entrance,new State("minecraft:glass"));breacher.tag.putInt("SiegeStuck",5);server.time+=20;Siege.tick(breacher,destination);ok(world.blocks.get(entrance).isAir(),"stalled zombie breaches window");world.blocks.put(entrance,new State("minecraft:stone"));breacher.tag.putInt("SiegeStuck",8);server.time+=20;Siege.tick(breacher,destination);ok(world.blocks.get(entrance).isAir(),"solid wall broken as fallback");world.blocks.put(entrance,new State("minecraft:barrel"));int edits=world.edits;breacher.tag.putInt("SiegeStuck",8);server.time+=20;Siege.tick(breacher,destination);ok(world.edits==edits,"storage survives breach attempts");world.blocks.clear();breacher.tag.putInt("SiegeStuck",10);server.time+=20;Siege.tick(breacher,new BlockPos(10,70,0));ok(world.blocks.values().stream().anyMatch(state->state.block().equals("minecraft:cobblestone")),"last resort creates a climbing step");world.blocks.clear();breacher.tag.putInt("SiegeBuilt",16);breacher.tag.putInt("SiegeStuck",10);server.time+=20;edits=world.edits;Siege.tick(breacher,new BlockPos(10,70,0));ok(world.edits==edits,"per mob building limit enforced");world.blocks.clear();world.blocks.put(new BlockPos(1,60,0),new State("minecraft:glass"));world.blocks.put(new BlockPos(4,60,0),new State("minecraft:oak_door"));Mob seeker=new Mob(world);seeker.nav.blocked=true;Siege.move(seeker,destination);ok(seeker.nav.targetX==4.5,"reachable door is preferred to closer window when direct route fails");Dispatcher dispatcher=new Dispatcher();DebugPve.register(new CommandEvent(dispatcher));ok(dispatcher.builder.name.equals("clanpvetest")&&dispatcher.builder.command!=null,"debug command registered with executable handler");chief.permission=0;ok(!dispatcher.builder.allowed.test(new CommandSource(chief)),"debug command hidden from non operators");chief.permission=2;ok(dispatcher.builder.allowed.test(new CommandSource(chief)),"debug command available to operator player");long before=profile.pveNext;chief.permission=0;DebugPve.start(chief);ok(profile.pveNext==before,"non operator cannot bypass PvE cooldown");System.out.println("PASS "+n+" nexus, PvE and territorial checks (API doubles)");}
